<template><div class="app-container"><h3>资料下载中心</h3><el-alert title="资料保存是草稿，点发布才公开；发布使用独立的资料发布权限，本期不套用文章/单页审核策略。下架或分类停用后，公开下载立即停止；已下载的访客副本无法撤回。" :closable="false"/>
 <el-tabs v-model="tab" @tab-change="loadTab"><el-tab-pane label="资料管理" name="resources"><el-form inline @submit.prevent="search"><el-form-item label="标题前缀"><el-input v-model="q.title" clearable maxlength="120"/></el-form-item><el-form-item label="分类"><DownloadPicker v-model="q.categoryId" allow-clear allow-disabled/></el-form-item><el-form-item label="状态"><el-select v-model="q.published" clearable style="width:140px"><el-option label="已发布" :value="1"/><el-option label="未发布" :value="0"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button v-hasPermi="['cms:download:add']" @click="edit()">新增资料</el-button><el-button v-hasPermi="['cms:download:query']" @click="files.open(false)">附件库</el-button><el-button @click="publicPage">打开前台下载中心</el-button></el-form-item></el-form>
 <el-table :data="rows" v-loading="loading"><el-table-column prop="downloadId" label="编号" width="80"/><el-table-column prop="title" label="草稿标题" min-width="180"/><el-table-column prop="categoryName" label="草稿分类"/><el-table-column prop="fileName" label="草稿附件" show-overflow-tooltip/><el-table-column label="状态" width="180"><template #default="s"><el-tag :type="s.row.isPublished?'success':'info'">{{s.row.isPublished?'已发布':'未发布'}}</el-tag><el-tag v-if="s.row.isPublished&&s.row.workingRevisionId!==s.row.publishedRevisionId" type="warning">有新稿</el-tag><el-tag v-if="!s.row.categoryEnabled" type="warning">草稿分类停用</el-tag></template></el-table-column><el-table-column label="操作" min-width="250"><template #default="s"><el-button v-hasPermi="['cms:download:edit']" link @click="edit(s.row)">编辑</el-button><el-button v-hasPermi="['cms:download:query']" link @click="history(s.row)">历史</el-button><el-button v-hasPermi="['cms:download:publish']" link type="success" @click="change(s.row,'publish')">发布</el-button><el-button v-if="s.row.isPublished" v-hasPermi="['cms:download:publish']" link @click="change(s.row,'unpublish')">下架</el-button><el-button v-hasPermi="['cms:download:remove']" link type="danger" @click="change(s.row,'remove')">删除</el-button></template></el-table-column></el-table><pagination v-if="total" :total="total" v-model:page="q.pageNum" v-model:limit="q.pageSize" @pagination="load"/></el-tab-pane>
 <el-tab-pane label="分类管理" name="categories"><el-form inline @submit.prevent="categorySearch"><el-form-item label="名称前缀"><el-input v-model="cq.name" clearable maxlength="60"/></el-form-item><el-button @click="categorySearch">查询</el-button><el-button v-hasPermi="['cms:download:category']" type="primary" @click="editCategory()">新增分类</el-button></el-form><el-table :data="categories"><el-table-column prop="categoryId" label="编号" width="80"/><el-table-column prop="name" label="分类名称"/><el-table-column prop="orderNum" label="顺序" width="100"/><el-table-column label="状态"><template #default="s">{{s.row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button v-hasPermi="['cms:download:category']" link @click="editCategory(s.row)">编辑</el-button><el-button v-hasPermi="['cms:download:category']" link type="danger" @click="removeCategory(s.row)">删除</el-button></template></el-table-column></el-table><pagination v-if="categoryTotal" :total="categoryTotal" v-model:page="cq.pageNum" v-model:limit="cq.pageSize" @pagination="loadCategories"/></el-tab-pane></el-tabs>
 <DownloadFiles ref="files" @selected="selectFile"/>
 <el-dialog v-model="editing" :title="form.downloadId?'编辑资料草稿':'新增资料草稿'" width="650px" append-to-body destroy-on-close><el-form label-width="110px" @submit.prevent="save"><el-form-item label="标题"><el-input v-model="form.title" maxlength="120"/></el-form-item><el-form-item label="说明"><el-input v-model="form.summary" type="textarea" maxlength="500"/></el-form-item><el-form-item label="分类"><DownloadPicker v-model="form.categoryId" :name="categoryName" allow-disabled/></el-form-item><el-form-item label="附件"><el-button @click="files.open(true)">{{fileName||'从附件库选择或上传'}}</el-button></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></template></el-dialog>
 <el-dialog v-model="categoryEditing" title="资料分类" width="500px" append-to-body destroy-on-close><el-form label-width="90px"><el-form-item label="名称"><el-input v-model="category.name" maxlength="60"/></el-form-item><el-form-item label="顺序"><el-input-number v-model="category.orderNum" :min="0" :max="9999"/></el-form-item><el-form-item label="启用"><el-switch v-model="category.enabled"/></el-form-item></el-form><template #footer><el-button @click="categoryEditing=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveCategory">保存</el-button></template></el-dialog>
 <el-dialog v-model="historyOpen" title="不可变资料历史（只读）" width="800px" append-to-body><el-table :data="revisions"><el-table-column prop="revisionNo" label="修订" width="70"/><el-table-column prop="title" label="标题"/><el-table-column prop="fileId" label="附件ID" width="100"/><el-table-column prop="createBy" label="保存人" width="100"/><el-table-column prop="createTime" label="时间" width="170"/></el-table><pagination v-if="historyTotal" :total="historyTotal" v-model:page="hpg.pageNum" v-model:limit="hpg.pageSize" @pagination="loadHistory"/></el-dialog>
</div></template>
<script setup>
import{ref,reactive,onMounted,onBeforeUnmount,onDeactivated,onActivated}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{workflow}from'@/api/cms/workflow';import DownloadPicker from'../components/DownloadPicker.vue';import DownloadFiles from'../components/DownloadFiles.vue'
const tab=ref('resources'),rows=ref([]),total=ref(0),loading=ref(false),busy=ref(false),files=ref(),editing=ref(false),form=reactive({}),categoryName=ref(''),fileName=ref(''),categories=ref([]),categoryTotal=ref(0),categoryEditing=ref(false),category=reactive({}),q=reactive({title:'',categoryId:0,published:undefined,pageNum:1,pageSize:10}),cq=reactive({name:'',pageNum:1,pageSize:10}),historyOpen=ref(false),revisions=ref([]),historyTotal=ref(0),hpg=reactive({pageNum:1,pageSize:10});let epoch=0,historyId=0,resume=false
async function load(){const n=epoch;loading.value=true;try{const r=await workflow('download/list','get',undefined,{...q});if(n===epoch){rows.value=r.rows;total.value=r.total}}finally{if(n===epoch)loading.value=false}}
function search(){q.pageNum=1;load()}async function loadCategories(){const n=epoch,r=await workflow('download/categories','get',undefined,{...cq});if(n===epoch){categories.value=r.rows;categoryTotal.value=r.total}}function categorySearch(){cq.pageNum=1;loadCategories()}function loadTab(){if(tab.value==='categories')loadCategories();else load()}
async function edit(row){if(row){const n=epoch,r=await workflow('download/'+row.downloadId);if(n!==epoch)return;Object.assign(form,{...r.data.draft,downloadId:r.data.downloadId,version:r.data.version});categoryName.value=row.categoryName;fileName.value=row.fileName}else{Object.assign(form,{downloadId:0,version:0,title:'',summary:'',categoryId:0,fileId:0});categoryName.value='';fileName.value=''};editing.value=true}
function selectFile(row){form.fileId=row.fileId;fileName.value=row.name}async function save(){if(busy.value)return;if(!form.title?.trim()||!form.categoryId||!form.fileId){ElMessage.warning('请填写标题并选择分类、附件');return};const n=epoch;busy.value=true;try{await workflow('download',form.downloadId?'put':'post',{...form});if(n!==epoch)return;editing.value=false;ElMessage.success('草稿已保存，尚未公开');await load()}finally{busy.value=false}}
async function change(row,action){const n=epoch;try{await ElMessageBox.confirm(action==='publish'?'确认将此草稿及附件公开供任何访客下载？':action==='remove'?'删除后停止公开，历史修订和附件引用继续保留？':'下架后停止公开下载，确认？','资料操作',{type:'warning'});if(n!==epoch)return;await workflow('download/'+row.downloadId+(action==='remove'?'':'/'+action),action==='remove'?'delete':'post',{version:row.version});await load()}catch{}}
function editCategory(row){Object.assign(category,row||{categoryId:0,version:0,name:'',orderNum:0,enabled:true});categoryEditing.value=true}async function saveCategory(){if(busy.value)return;if(!category.name?.trim()){ElMessage.warning('请填写分类名称');return};busy.value=true;try{await workflow('download/categories','post',{...category});categoryEditing.value=false;await loadCategories();await load()}finally{busy.value=false}}async function removeCategory(row){const n=epoch;try{await ElMessageBox.confirm('仅未被任何历史资料引用的分类可删除；有引用时请停用。','删除分类');if(n!==epoch)return;await workflow('download/categories/'+row.categoryId,'delete',{version:row.version});await loadCategories()}catch{}}
async function history(row){historyId=row.downloadId;hpg.pageNum=1;historyOpen.value=true;await loadHistory()}async function loadHistory(){const n=epoch,r=await workflow(`download/${historyId}/history`,'get',undefined,{...hpg});if(n===epoch){revisions.value=r.rows;historyTotal.value=r.total}}function publicPage(){window.open('/downloads','_blank','noopener,noreferrer')}
function close(){++epoch;editing.value=false;categoryEditing.value=false;historyOpen.value=false;files.value?.close()}onMounted(load);onBeforeUnmount(close);onDeactivated(()=>{resume=true;close()});onActivated(()=>{if(resume){resume=false;loadTab()}})
</script>
